161	static std::string detect_arch(const std::string& path) {
162	  std::ifstream f(path, std::ios::binary);
163	  if (!f) return "";
164	  uint8_t buf[20];
165	  f.read(reinterpret_cast<char*>(buf), 20);
166	  if (!f || buf[0] != 0x7f || buf[1] != 'E' || buf[2] != 'L' || buf[3] != 'F')
167	    return "";
168	  uint16_t e_machine = static_cast<uint16_t>(buf[18]) | (static_cast<uint16_t>(buf[19]) << 8);
169	  if (e_machine != 0xF3) return "";  // not RISC-V (EM_RISCV=243)
170	  return (buf[4] == ELFCLASS64) ? "riscv64" : "riscv32";
171	}
