190	// Run argv with stdout+stderr redirected to /dev/null; chdir to cwd if set.
191	// Returns child exit code, 128+signal if killed, -1 on fork failure.
192	static int run_silent(const std::vector<std::string>& argv, const std::string& cwd) {
193	  if (argv.empty()) return -1;
194	  pid_t pid = fork();
195	  if (pid < 0) return -1;
196	  if (pid == 0) {
197	    if (!cwd.empty() && chdir(cwd.c_str()) != 0) _exit(127);
198	    int devnull = open("/dev/null", O_RDWR);
199	    if (devnull >= 0) {
200	      dup2(devnull, STDIN_FILENO);
201	      dup2(devnull, STDOUT_FILENO);
202	      dup2(devnull, STDERR_FILENO);
203	      if (devnull > 2) close(devnull);
204	    }
205	    std::vector<char*> cargv;
206	    cargv.reserve(argv.size() + 1);
207	    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
208	    cargv.push_back(nullptr);
209	    execvp(cargv[0], cargv.data());
210	    _exit(127);
211	  }
212	  int status = 0;
213	  waitpid(pid, &status, 0);
214	  if (WIFEXITED(status)) return WEXITSTATUS(status);
215	  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
216	  return -1;
217	}
