219	// Write lines to argv's stdin; capture its stdout. Used for addr2line.
220	static std::string capture_with_stdin(const std::vector<std::string>& argv,
221	                                       const std::string& input) {
222	  if (argv.empty()) return "";
223	  int in_fds[2], out_fds[2];
224	  if (pipe(in_fds) != 0) return "";
225	  if (pipe(out_fds) != 0) { close(in_fds[0]); close(in_fds[1]); return ""; }
226	  pid_t pid = fork();
227	  if (pid < 0) {
228	    close(in_fds[0]); close(in_fds[1]);
229	    close(out_fds[0]); close(out_fds[1]);
230	    return "";
231	  }
232	  if (pid == 0) {
233	    close(in_fds[1]); close(out_fds[0]);
234	    dup2(in_fds[0], STDIN_FILENO);
235	    dup2(out_fds[1], STDOUT_FILENO);
236	    int devnull = open("/dev/null", O_WRONLY);
237	    if (devnull >= 0) { dup2(devnull, STDERR_FILENO); if (devnull > 2) close(devnull); }
238	    close(in_fds[0]); close(out_fds[1]);
239	    std::vector<char*> cargv;
240	    cargv.reserve(argv.size() + 1);
241	    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
242	    cargv.push_back(nullptr);
243	    execvp(cargv[0], cargv.data());
244	    _exit(127);
245	  }
246	  close(in_fds[0]); close(out_fds[1]);
247	  // Write input then close to signal EOF.
248	  const char* p = input.data();
249	  size_t rem = input.size();
250	  while (rem > 0) {
251	    ssize_t w = write(in_fds[1], p, rem);
252	    if (w < 0) break;
253	    p += w; rem -= static_cast<size_t>(w);
254	  }
255	  close(in_fds[1]);
256	  std::string out;
257	  char buf[4096];
258	  ssize_t n;
259	  while ((n = read(out_fds[0], buf, sizeof(buf))) > 0)
260	    out.append(buf, static_cast<size_t>(n));
261	  close(out_fds[0]);
262	  waitpid(pid, nullptr, 0);
263	  return out;
264	}
