266	static bool cmd_exists(const std::string& cmd) {
267	  if (cmd.find('/') != std::string::npos)
268	    return access(cmd.c_str(), X_OK) == 0;
269	  const char* path_env = getenv("PATH");
270	  if (!path_env) return false;
271	  std::istringstream ss(path_env);
272	  std::string dir;
273	  while (std::getline(ss, dir, ':')) {
274	    if (!dir.empty() && access((dir + "/" + cmd).c_str(), X_OK) == 0) return true;
275	  }
276	  return false;
277	}
