292	static std::vector<LogEntry> parse_log(const std::string& path) {
293	  std::vector<LogEntry> rows;
294	  std::ifstream f(path);
295	  if (!f) return rows;
296	  static const std::regex re(R"(\s*(0x[0-9a-fA-F]+)\s*,\s*(0x[0-9a-fA-F]+)\s*,\s*(\d+))");
297	  std::string line;
298	  while (std::getline(f, line)) {
299	    std::smatch m;
300	    if (!std::regex_search(line, m, re)) continue;
301	    rows.push_back({
302	      std::stoull(m[1], nullptr, 16),
303	      std::stoull(m[2], nullptr, 16),
304	      std::stoull(m[3])
305	    });
306	  }
307	  return rows;
308	}
