310	// ─── Disassembly parsing ─────────────────────────────────────────────────────
311	
312	struct InsnInfo {
313	  std::string mnemonic;
314	  std::string operands;
315	};
316	
317	static std::map<uint64_t, InsnInfo> parse_disasm(const std::string& raw) {
318	  std::map<uint64_t, InsnInfo> m;
319	  std::istringstream ss(raw);
320	  // Matches: optional leading whitespace, hex digits, colon, whitespace,
321	  // then mnemonic.  Works for both GNU and LLVM objdump.
322	  static const std::regex re(R"(^\s*([0-9a-fA-F]+):\s+(\S+)(?:\s+(.*))?$)");
323	  std::string line;
324	  while (std::getline(ss, line)) {
325	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
326	      line.pop_back();
327	    std::smatch sm;
328	    if (!std::regex_match(line, sm, re)) continue;
329	    uint64_t pc;
330	    try { pc = std::stoull(sm[1], nullptr, 16); } catch (...) { continue; }
331	    std::string mn = sm[2];
332	    std::string ops = sm.size() > 3 ? sm[3].str() : "";
333	    // Trim trailing whitespace from ops.
334	    while (!ops.empty() && (ops.back() == ' ' || ops.back() == '\t')) ops.pop_back();
335	    m[pc] = {std::move(mn), std::move(ops)};
336	  }
337	  return m;
338	}
339	
340	static bool is_rvv(const std::string& mn) {
341	  if (mn.size() < 2) return false;
342	  char lo = static_cast<char>(tolower(static_cast<unsigned char>(mn[0])));
343	  return lo == 'v' && std::isalpha(static_cast<unsigned char>(mn[1]));
344	}
345	
346	struct RvvInsn { uint64_t pc; std::string mn, ops; };
347	struct CallInsn { uint64_t pc; std::string mn, target; };
348	
349	static const std::set<std::string> CALL_MN = {"jal","jalr","c.jal","c.jalr"};
350	
351	static std::vector<RvvInsn> rvv_in_range(
352	    const std::map<uint64_t, InsnInfo>& disasm,
353	    uint64_t s, uint64_t e)
354	{
355	  std::vector<RvvInsn> out;
356	  auto it = disasm.lower_bound(s);
357	  while (it != disasm.end() && it->first <= e) {
358	    if (is_rvv(it->second.mnemonic))
359	      out.push_back({it->first, it->second.mnemonic, it->second.operands});
360	    ++it;
361	  }
362	  return out;
363	}
364	
365	static std::vector<CallInsn> calls_in_range(
366	    const std::map<uint64_t, InsnInfo>& disasm,
367	    uint64_t s, uint64_t e)
368	{
369	  std::vector<CallInsn> out;
370	  static const std::regex callee_re("<([^>]+)>");
371	  auto it = disasm.lower_bound(s);
372	  while (it != disasm.end() && it->first <= e) {
373	    std::string lo = it->second.mnemonic;
374	    std::transform(lo.begin(), lo.end(), lo.begin(),
375	                   [](unsigned char c){ return tolower(c); });
376	    if (CALL_MN.count(lo)) {
377	      std::smatch m;
378	      std::string target = "(indirect)";
379	      if (std::regex_search(it->second.operands, m, callee_re))
380	        target = m[1];
381	      out.push_back({it->first, it->second.mnemonic, target});
382	    }
383	    ++it;
384	  }
385	  return out;
386	}
