388	// ─── Source line resolution ──────────────────────────────────────────────────
389	
390	static std::map<uint64_t, std::string> resolve_sources(
391	    const std::string& addr2line_bin,
392	    const std::string& elf_path,
393	    const std::vector<uint64_t>& pcs)
394	{
395	  std::map<uint64_t, std::string> result;
396	  if (addr2line_bin.empty() || pcs.empty()) return result;
397	
398	  // Build input: one hex address per line.
399	  std::string input;
400	  for (uint64_t pc : pcs) {
401	    char buf[20]; snprintf(buf, sizeof(buf), "0x%llx\n", (unsigned long long)pc);
402	    input += buf;
403	  }
404	
405	  std::string out = capture_with_stdin({addr2line_bin, "-e", elf_path}, input);
406	
407	  // One output line per input address.
408	  std::istringstream ss(out);
409	  std::string line;
410	  size_t idx = 0;
411	  while (std::getline(ss, line) && idx < pcs.size()) {
412	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
413	      line.pop_back();
414	    if (!line.empty() && line.find("??") == std::string::npos)
415	      result[pcs[idx]] = line;
416	    ++idx;
417	  }
418	  return result;
419	}
420	
421	static std::string src_basename(const std::string& s) {
422	  if (s.empty()) return "";
423	  // "path:line[ (extra)]" -> "basename(path):line[ ...]"
424	  auto sp = s.find(' ');
425	  std::string head = (sp != std::string::npos) ? s.substr(0, sp) : s;
426	  std::string tail = (sp != std::string::npos) ? s.substr(sp) : "";
427	  auto slash = head.rfind('/');
428	  return ((slash != std::string::npos) ? head.substr(slash + 1) : head) + tail;
429	}
430	
431	static std::pair<std::string,int> parse_file_line(const std::string& s) {
432	  if (s.empty() || s.rfind("??", 0) == 0) return {"", 0};
433	  static const std::regex re(R"(^(.+?):(\d+)(?::\d+)?(?:\s|$))");
434	  std::smatch m;
435	  if (!std::regex_search(s, m, re)) return {"", 0};
436	  return {m[1], std::stoi(m[2])};
437	}
438	
439	static std::string read_source_line(const std::string& path, int lineno) {
440	  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
441	  std::ifstream f(path);
442	  std::string line;
443	  for (int i = 1; std::getline(f, line); ++i) {
444	    if (i == lineno) {
445	      while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
446	                                line.back() == ' '  || line.back() == '\t'))
447	        line.pop_back();
448	      auto s = line.find_first_not_of(" \t");
449	      return (s != std::string::npos) ? line.substr(s) : line;
450	    }
451	  }
452	  return "";
453	}
