455	// ─── Loop structures + nesting ───────────────────────────────────────────────
456	
457	struct Loop {
458	  std::string id;
459	  uint64_t start, end, iters;
460	  Loop* parent = nullptr;
461	  std::vector<Loop*> children;
462	};
463	
464	static std::vector<Loop> build_loops(
465	    const std::vector<LogEntry>& rows, int limit)
466	{
467	  std::vector<Loop> loops;
468	  int n = std::min(static_cast<int>(rows.size()), limit);
469	  loops.reserve(static_cast<size_t>(n));
470	  for (int i = 0; i < n; ++i)
471	    loops.push_back({"L" + std::to_string(i + 1),
472	                     rows[static_cast<size_t>(i)].start,
473	                     rows[static_cast<size_t>(i)].end,
474	                     rows[static_cast<size_t>(i)].iters,
475	                     nullptr, {}});
476	
477	  // Compute parent: smallest enclosing range.
478	  for (auto& loop : loops) {
479	    Loop* best = nullptr;
480	    uint64_t best_sz = UINT64_MAX;
481	    for (auto& cand : loops) {
482	      if (&cand == &loop) continue;
483	      if (cand.start == loop.start && cand.end == loop.end) continue; // identical
484	      if (cand.start <= loop.start && loop.end <= cand.end) {
485	        uint64_t sz = cand.end - cand.start;
486	        if (sz < best_sz) { best = &cand; best_sz = sz; }
487	      }
488	    }
489	    loop.parent = best;
490	  }
491	  for (auto& loop : loops)
492	    if (loop.parent) loop.parent->children.push_back(&loop);
493	
494	  return loops;
495	}
