504	static void print_table(
505	    const std::vector<LogEntry>& rows,
506	    const std::string& elf_path,
507	    const std::map<uint64_t, std::string>& src_map,
508	    int min_iters, bool optimize_rvv)
509	{
510	  bool have_src = !src_map.empty();
511	
512	  auto srcpair = [&](uint64_t s, uint64_t e) -> std::string {
513	    std::string a = src_short(src_map, s), b = src_short(src_map, e);
514	    if (!a.empty() && a == b) return a;
515	    return (a.empty() ? "?" : a) + " -> " + (b.empty() ? "?" : b);
516	  };
517	
518	  printf("# hot loops (iters >= %d", min_iters);
519	  if (optimize_rvv) printf(", RVV-only");
520	  printf("), sorted desc, top %zu\n", rows.size());
521	
522	  size_t w_iter = 5;  // strlen("iters")
523	  for (const auto& r : rows) {
524	    char buf[24]; snprintf(buf, sizeof(buf), "%llu", (unsigned long long)r.iters);
525	    w_iter = std::max(w_iter, strlen(buf));
526	  }
527	  const size_t w_pc = 18;
528	  size_t w_sym = 8;  // strlen("location")
529	  for (const auto& r : rows) {
530	    std::string loc = sym_at(elf_path, r.start) + " -> " + sym_at(elf_path, r.end);
531	    w_sym = std::max(w_sym, loc.size());
532	  }
533	
534	  if (have_src) {
535	    printf("%*s | %-*s -> %-*s | %-*s | source\n",
536	           static_cast<int>(w_iter), "iters",
537	           static_cast<int>(w_pc), "start_pc",
538	           static_cast<int>(w_pc), "end_pc",
539	           static_cast<int>(w_sym), "location");
540	  } else {
541	    printf("%*s | %-*s -> %-*s | location\n",
542	           static_cast<int>(w_iter), "iters",
543	           static_cast<int>(w_pc), "start_pc",
544	           static_cast<int>(w_pc), "end_pc");
545	  }
546	  size_t sep = w_iter + 3 + w_pc + 4 + w_pc + 3 + w_sym;
547	  if (have_src) sep += 3 + 12;
548	  printf("%s\n", std::string(sep, '-').c_str());
549	
550	  for (const auto& r : rows) {
551	    std::string loc = sym_at(elf_path, r.start) + " -> " + sym_at(elf_path, r.end);
552	    if (have_src)
553	      printf("%*llu | 0x%016llx -> 0x%016llx | %-*s | %s\n",
554	             static_cast<int>(w_iter), (unsigned long long)r.iters,
555	             (unsigned long long)r.start, (unsigned long long)r.end,
556	             static_cast<int>(w_sym), loc.c_str(),
557	             srcpair(r.start, r.end).c_str());
558	    else
559	      printf("%*llu | 0x%016llx -> 0x%016llx | %s\n",
560	             static_cast<int>(w_iter), (unsigned long long)r.iters,
561	             (unsigned long long)r.start, (unsigned long long)r.end,
562	             loc.c_str());
563	  }
564	}
