566	// ─── Output: LLM Markdown ────────────────────────────────────────────────────
567	
568	static void print_llm(
569	    const std::vector<Loop>& loops,
570	    uint64_t total_iters_all,
571	    const std::string& elf_path,
572	    const std::map<uint64_t, std::string>& src_map,
573	    const std::map<uint64_t, InsnInfo>& disasm,
574	    int min_iters, bool optimize_rvv)
575	{
576	  auto pct = [&](uint64_t n) -> double {
577	    return total_iters_all ? 100.0 * n / total_iters_all : 0.0;
578	  };
579	  auto src_full = [&](uint64_t pc) -> std::string {
580	    auto it = src_map.find(pc); return it != src_map.end() ? it->second : "";
581	  };
582	
583	  // Header + TL;DR
584	  {
585	    const auto& top = loops[0];
586	    auto rvv = rvv_in_range(disasm, top.start, top.end);
587	    std::string rvv_str;
588	    if (!rvv.empty()) {
589	      std::vector<std::string> uniq;
590	      for (const auto& r : rvv)
591	        if (std::find(uniq.begin(), uniq.end(), r.mn) == uniq.end())
592	          uniq.push_back(r.mn);
593	      rvv_str = "RVV (";
594	      for (size_t i = 0; i < std::min(uniq.size(), size_t{3}); ++i) {
595	        if (i) rvv_str += ", ";
596	        rvv_str += uniq[i];
597	      }
598	      if (uniq.size() > 3) { rvv_str += ", +" + std::to_string(uniq.size()-3) + " more"; }
599	      rvv_str += ")";
600	    } else {
601	      rvv_str = "scalar";
602	    }
603	    std::string fn = sym_func_at(elf_path, top.start);
604	    std::string src_s = src_short(src_map, top.start); if (src_s.empty()) src_s = "?";
605	    std::string nest_str = top.parent
606	                         ? "nested inside " + top.parent->id
607	                         : "top-level (no parent loop)";
608	    std::string child_str;
609	    if (!top.children.empty()) {
610	      child_str = "and contains " + std::to_string(top.children.size()) + " inner loop(s): ";
611	      for (size_t i = 0; i < top.children.size(); ++i) {
612	        if (i) child_str += ", ";
613	        child_str += top.children[i]->id;
614	      }
615	    } else {
616	      child_str = "and contains no inner loop";
617	    }
618	    printf("# Hotloops Report\n");
619	    printf("target:           %s\n", fs::path(elf_path).filename().c_str());
620	    printf("total_iters:      %llu\n", (unsigned long long)total_iters_all);
621	    printf("reported_loops:   %zu\n", loops.size());
622	    printf("min_iters:        %d\n", min_iters);
623	    printf("rvv_filter:       %s\n", optimize_rvv ? "on" : "off");
624	    printf("\n## TL;DR\n");
625	    printf("Hottest loop is %s in `%s` (%s), %llu iters = %.1f%% of total. "
626	           "Body is %s. It is %s, %s.\n",
627	           top.id.c_str(), fn.c_str(), src_s.c_str(),
628	           (unsigned long long)top.iters, pct(top.iters),
629	           rvv_str.c_str(), nest_str.c_str(), child_str.c_str());
630	    printf("\n## Loops\n");
631	  }
632	
633	  for (size_t idx = 0; idx < loops.size(); ++idx) {
634	    const auto& loop = loops[idx];
635	    printf("\n### %s%s  (%.1f%% of total)\n",
636	           loop.id.c_str(), idx == 0 ? " [hottest]" : "", pct(loop.iters));
637	    printf("iters:        %llu\n", (unsigned long long)loop.iters);
638	    printf("function:     %s -> %s\n",
639	           sym_at(elf_path, loop.start).c_str(),
640	           sym_at(elf_path, loop.end).c_str());
641	
642	    // measure: whole enclosing function (entry -> ret).
643	    auto [fn_entry, fn_end] = andes_sim::fn_range(elf_path, loop.start);
644	    if (fn_entry != 0 && fn_end != 0) {
645	      uint64_t ret_pc = fn_end - 4;  // safe default (standard ret is 4 bytes)
646	      auto it = disasm.lower_bound(fn_end);
647	      if (it != disasm.begin()) { --it; if (it->first >= fn_entry) ret_pc = it->first; }
648	      printf("measure:      --pc-start 0x%llx --pc-end 0x%llx"
649	             "  (all of %s: entry -> ret)\n",
650	             (unsigned long long)fn_entry, (unsigned long long)ret_pc,
651	             sym_func_at(elf_path, loop.start).c_str());
652	    }
653	
654	    std::string sf = src_full(loop.start), se = src_full(loop.end);
655	    if (!sf.empty() && !se.empty() && sf == se)
656	      printf("source:       %s\n", src_basename(sf).c_str());
657	    else
658	      printf("source:       %s -> %s\n",
659	             (sf.empty() ? "?" : src_basename(sf)).c_str(),
660	             (se.empty() ? "?" : src_basename(se)).c_str());
661	
662	    {
663	      auto [path, lineno] = parse_file_line(sf);
664	      std::string snippet = read_source_line(path, lineno);
665	      if (!snippet.empty()) {
666	        if (snippet.size() > 200) snippet = snippet.substr(0, 197) + "...";
667	        printf("code:         %s\n", snippet.c_str());
668	      }
669	    }
670	
671	    auto rvv = rvv_in_range(disasm, loop.start, loop.end);
672	    if (!rvv.empty()) {
673	      printf("rvv:          yes (%zu insn%s)\n", rvv.size(), rvv.size() == 1 ? "" : "s");
674	      printf("rvv_insns:\n");
675	      for (size_t i = 0; i < std::min(rvv.size(), size_t{8}); ++i)
676	        printf("  - 0x%llx  %-10s %s\n",
677	               (unsigned long long)rvv[i].pc, rvv[i].mn.c_str(), rvv[i].ops.c_str());
678	      if (rvv.size() > 8) printf("  - ... (%zu more)\n", rvv.size() - 8);
679	    } else {
680	      printf("rvv:          no\n");
681	    }
682	
683	    printf("parent:       %s\n", loop.parent ? loop.parent->id.c_str() : "-");
684	    if (!loop.children.empty()) {
685	      printf("children:     [");
686	      for (size_t i = 0; i < loop.children.size(); ++i) {
687	        if (i) printf(", ");
688	        printf("%s", loop.children[i]->id.c_str());
689	      }
690	      printf("]\n");
691	    } else {
692	      printf("children:     []\n");
693	    }
694	
695	    auto callees = calls_in_range(disasm, loop.start, loop.end);
696	    if (!callees.empty()) {
697	      printf("calls:\n");
698	      for (size_t i = 0; i < std::min(callees.size(), size_t{8}); ++i)
699	        printf("  - 0x%llx  %s -> %s\n",
700	               (unsigned long long)callees[i].pc,
701	               callees[i].mn.c_str(), callees[i].target.c_str());
702	      if (callees.size() > 8) printf("  - ... (%zu more)\n", callees.size() - 8);
703	    } else {
704	      printf("calls:        []\n");
705	    }
706	  }
707	}
