709	// ─── Main ─────────────────────────────────────────────────────────────────────
710	
711	int main(int argc, char** argv) {
712	  Config cfg = parse_args(argc, argv);
713	
714	  // Arch detection.
715	  if (cfg.arch == "auto") {
716	    cfg.arch = detect_arch(cfg.elf);
717	    if (cfg.arch.empty()) {
718	      fprintf(stderr, "error: cannot auto-detect arch (not RISC-V?), pass --arch\n");
719	      return 2;
720	    }
721	  }
722	
723	  // Locate QEMU binary. QEMU is integrated as an external prebuilt binary:
724	  // QEMU_BIN_DIR (config.env, exported by setup.sh) holds qemu-system-{arch}.
725	  if (cfg.qemu.empty()) {
726	    if (const char* dir = std::getenv("QEMU_BIN_DIR"); dir && *dir) {
727	      cfg.qemu = std::string(dir) + "/qemu-system-" + cfg.arch;
728	    } else {
729	      try {
730	        cfg.qemu = (andes_sim::repo_root() / "build" / "qemu" /
731	                    ("qemu-system-" + cfg.arch)).string();
732	      } catch (...) {
733	        cfg.qemu = "qemu-system-" + cfg.arch;
734	      }
735	    }
736	  }
737	  if (!fs::is_regular_file(cfg.qemu) || access(cfg.qemu.c_str(), X_OK) != 0) {
738	    fprintf(stderr, "error: qemu not found/executable: %s\n", cfg.qemu.c_str());
739	    return 2;
740	  }
741	
742	  // Locate hotloops plugin.
743	  if (cfg.plugin.empty()) {
744	    try {
745	      cfg.plugin = (andes_sim::repo_root() / "build" / "qemu" /
746	                    "contrib" / "plugins" / "libhotloops.so").string();
747	    } catch (...) {}
748	  }
749	  if (!fs::is_regular_file(cfg.plugin)) {
750	    fprintf(stderr, "error: plugin not built: %s\n", cfg.plugin.c_str());
751	    return 2;
752	  }
753	
754	  // Temp log file.
755	  TempFile log_file;
756	
757	  // Build QEMU command.
758	  std::string plugin_arg = cfg.plugin +
759	                           ",limit=" + std::to_string(cfg.limit) +
760	                           ",min_iters=" + std::to_string(cfg.min_iters);
761	  std::vector<std::string> qemu_cmd = {
762	    cfg.qemu,
763	    "-plugin", plugin_arg,
764	    "-d", "plugin", "-D", log_file.path,
765	    "-M", cfg.machine,
766	    "-cpu", cfg.cpu,
767	    "-nographic", "-semihosting",
768	    "-bios", cfg.elf
769	  };
770	  if (!cfg.qemu_config.empty()) { qemu_cmd.push_back("-readconfig"); qemu_cmd.push_back(cfg.qemu_config); }
771	  for (const auto& a : cfg.extra_qemu_args) qemu_cmd.push_back(a);
772	
773	  run_silent(qemu_cmd, cfg.qemu_cwd);
774	
775	  // --raw: dump log and exit.
776	  if (cfg.raw) {
777	    std::ifstream f(log_file.path);
778	    std::cout << f.rdbuf();
779	    return 0;
780	  }
781	
782	  // Parse log.
783	  auto rows = parse_log(log_file.path);
784	  if (rows.empty()) {
785	    fprintf(stderr, "hotloops: no backward edges observed\n");
786	    return 0;
787	  }
788	  uint64_t total_iters_all = 0;
789	  for (const auto& r : rows) total_iters_all += r.iters;
790	
791	  // Locate objdump. Prefer the cross objdump from $HYBRID_TOOLCHAIN so that
792	  // RISC-V vendor extensions (RVV, Andes custom) are decoded correctly.
793	  // Generic llvm-objdump on old distros (e.g. LLVM 14) may not support RVV.
794	  if (cfg.objdump.empty()) {
795	    // Resolve HYBRID_TOOLCHAIN: env var first, then config.env in repo root.
796	    std::string hybrid_tc;
797	    if (const char* tc = std::getenv("HYBRID_TOOLCHAIN"); tc && *tc) {
798	      hybrid_tc = tc;
799	    } else {
800	      try {
801	        std::ifstream cenv(andes_sim::repo_root() / "config.env");
802	        std::string line;
803	        while (std::getline(cenv, line)) {
804	          auto eq = line.find('=');
805	          if (eq == std::string::npos) continue;
806	          if (line.substr(0, eq) == "HYBRID_TOOLCHAIN")
807	            hybrid_tc = line.substr(eq + 1);
808	        }
809	      } catch (...) {}
810	    }
811	    std::vector<std::string> cands;
812	    if (!hybrid_tc.empty()) {
813	      std::string tcbin = hybrid_tc + "/bin/";
814	      cands.push_back(tcbin + "riscv64-unknown-elf-objdump");
815	      cands.push_back(tcbin + "riscv32-unknown-elf-objdump");
816	    }
817	    cands.insert(cands.end(), {"riscv64-unknown-elf-objdump",
818	                               "riscv32-unknown-elf-objdump",
819	                               "llvm-objdump", "objdump"});
820	    cfg.objdump = find_first(cands);
821	  }
822	
823	  // Build disassembly map (needed for RVV filter and --llm).
824	  std::map<uint64_t, InsnInfo> disasm;
825	  if (!cfg.objdump.empty() && (cfg.optimize_rvv || cfg.llm)) {
826	    std::string raw = andes_sim::run_process(
827	      {cfg.objdump, "-d", "--no-show-raw-insn", cfg.elf}, 60000).out;
828	    disasm = parse_disasm(raw);
829	  }
830	
831	  // Filter rows.
832	  rows.erase(std::remove_if(rows.begin(), rows.end(),
833	    [&](const LogEntry& r){ return static_cast<int>(r.iters) < cfg.min_iters; }),
834	    rows.end());
835	  if (cfg.optimize_rvv) {
836	    rows.erase(std::remove_if(rows.begin(), rows.end(),
837	      [&](const LogEntry& r){ return rvv_in_range(disasm, r.start, r.end).empty(); }),
838	      rows.end());
839	  }
840	  std::sort(rows.begin(), rows.end(),
841	            [](const LogEntry& a, const LogEntry& b){ return a.iters > b.iters; });
842	  if (static_cast<int>(rows.size()) > cfg.limit)
843	    rows.resize(static_cast<size_t>(cfg.limit));
844	
845	  if (rows.empty()) {
846	    fprintf(stderr, "hotloops: no loops with iters >= %d%s\n",
847	            cfg.min_iters, cfg.optimize_rvv ? " containing RVV instructions" : "");
848	    return 0;
849	  }
850	
851	  // Source line resolution.
852	  std::map<uint64_t, std::string> src_map;
853	  if (!cfg.no_source) {
854	    if (cfg.addr2line_bin.empty())
855	      cfg.addr2line_bin = find_first({"llvm-addr2line", "addr2line",
