23	bool slurp(const std::string& path, std::vector<char>& buf) {
24	  std::ifstream f(path, std::ios::binary);
25	  if (!f) return false;
26	  std::ostringstream ss;
27	  ss << f.rdbuf();
28	  const std::string s = ss.str();
29	  buf.assign(s.begin(), s.end());
30	  return true;
31	}
32	
33	// memcpy a POD header out of the buffer at `off`; false if it would overrun
34	// (buffers may be truncated/malformed -- never read past the end).
35	template <class T>
36	bool load(const std::vector<char>& buf, size_t off, T& out) {
37	  if (off + sizeof(T) > buf.size()) return false;
38	  std::memcpy(&out, buf.data() + off, sizeof(T));
39	  return true;
40	}
41	
42	// Slurp `path` and validate its ELFCLASS64 header into `eh`. Returns false and
43	// sets `err` (unreadable / not-ELF / not-RV64) on failure, clears `err` on ok.
44	// Shared prologue for every ELF reader below.
45	bool read_elf64_header(const std::string& path, std::vector<char>& buf,
46	                       Elf64_Ehdr& eh, std::string& err) {
47	  err.clear();
48	  if (!slurp(path, buf)) {
49	    err = "cannot read ELF '" + path + "'";
50	    return false;
51	  }
52	  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
53	    err = "not an ELF file: " + path;
54	    return false;
55	  }
56	  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
57	    err = "not an RV64 (ELFCLASS64) file: " + path;
58	    return false;
59	  }
60	  return true;
61	}
62	
63	}  // namespace
64	
65	std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
66	                       std::string& err) {
67	  err.clear();
68	
69	  // A "0x"/"0X" address is used verbatim with the prefix stripped (roi.sh
70	  // `${boundary#0[xX]}`); the .symtab is never touched.
71	  if (boundary.starts_with("0x") || boundary.starts_with("0X")) {
72	    std::string addr = boundary.substr(2);
73	    // Must be all hex digits: a verbatim pass of e.g. "ZZZ"/"10zz" would let the
74	    // downstream strtoull silently truncate to 0x0/0x10 (wrong PC window).
75	    if (addr.empty() ||
76	        addr.find_first_not_of("0123456789abcdefABCDEF") != std::string::npos) {
77	      err = "malformed address '" + boundary + "'";
78	      return "";
79	    }
80	    return addr;
81	  }
82	
83	  std::vector<char> buf;
84	  Elf64_Ehdr eh;
85	  if (!read_elf64_header(elf_path, buf, eh, err)) return "";
86	
87	  // Scan section headers for a symbol table; resolve names through its linked
88	  // string table (sh_link).
89	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
90	    Elf64_Shdr sym_sh;
91	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
92	      break;
93	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
94	
95	    Elf64_Shdr str_sh;
96	    if (sym_sh.sh_link >= eh.e_shnum ||
97	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
98	              str_sh))
99	      continue;
100	
101	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
102	    for (size_t s = 0; s < nsym; ++s) {
103	      Elf64_Sym sym;
104	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
105	      if (sym.st_shndx == SHN_UNDEF) continue;  // --defined-only
106	
107	      const size_t noff = str_sh.sh_offset + sym.st_name;
108	      if (noff >= buf.size()) continue;
109	      const char* name = buf.data() + noff;
110	      const size_t avail = buf.size() - noff;
111	      if (::strnlen(name, avail) == avail) continue;  // unterminated in bounds
112	      if (boundary == name) return to_hex(sym.st_value);
113	    }
114	  }
115	
116	  err = "symbol '" + boundary + "' not defined in " + elf_path;
117	  return "";
118	}
