120	uint64_t elf_entry(const std::string& elf_path, std::string& err) {
121	  std::vector<char> buf;
122	  Elf64_Ehdr eh;
123	  if (!read_elf64_header(elf_path, buf, eh, err)) return 0;
124	  return eh.e_entry;
125	}
